let step, i=0, num=26;
let theta;

function setup() {
  createCanvas(500, 500);

  step=height/num;

}

function draw() {
  background(20);
  fill("#FFB700");
  noStroke();
  ellipse(width/2,height/2,width*.6, height*.6);
  i=0;
  for (let y=2*step; y<height-2*step+1; y += step) {
    let sw = map(sin(theta+(TWO_PI/num*i)), -1, 1, 1.5, 12);
    let edge = 2*step;
    stroke(20);
    strokeWeight(sw);
    line(edge, y, width-edge, y);
    i++;
  }
  theta += .0523;

  //if (frameCount%1==0 && frameCount<121) saveFrame("image-###.gif");

}
